import re, glob
ax = open('/tmp/ax.txt').read()
leaks = {}
for e in re.split(r"\n(?=')", ax.strip()):
    m = re.match(r"'([^']+)'", e)
    if m: leaks[m.group(1)] = 'sorryAx' in e
STMT = {'theorem','lemma','proposition','corollary','definition','remark','example','notation','convention'}
def strip_c(s): return re.sub(r'(?<!\\)%[^\n]*', '', s)
defects=[]; attached=0; orphan_proofs=0
for fn in sorted(glob.glob('blueprint/src/chapters/*.tex')):
    txt = strip_c(open(fn).read())
    # sequential scan of every env begin/end at top level of interest
    toks = [(m.start(), m.group(1), m.group(2)) for m in
            re.finditer(r'\\(begin|end)\{(' + '|'.join(STMT|{'proof'}) + r')\}', txt)]
    cur=None  # (label, decls, endpos)
    i=0
    while i < len(toks):
        pos, be, env = toks[i]
        if be=='begin' and env in STMT:
            # find matching end
            depth=1; j=i+1
            while j < len(toks) and depth>0:
                if toks[j][2]==env: depth += 1 if toks[j][1]=='begin' else -1
                j+=1
            end = toks[j-1][0] if j-1<len(toks) else len(txt)
            body = txt[pos:end]
            lab=re.search(r'\\label\{([^}]*)\}',body); lean=re.search(r'\\lean\{([^}]*)\}',body)
            cur=(lab.group(1) if lab else None,
                 [x.strip() for x in lean.group(1).split(',')] if lean else [])
            i+=1
        elif be=='begin' and env=='proof':
            depth=1; j=i+1
            while j < len(toks) and depth>0:
                if toks[j][2]=='proof': depth += 1 if toks[j][1]=='begin' else -1
                j+=1
            end = toks[j-1][0] if j-1<len(toks) else len(txt)
            pbody = txt[pos:end]
            if cur is None: orphan_proofs+=1
            else:
                attached+=1
                if '\\leanok' in pbody:
                    for d in cur[1]:
                        if leaks.get(d):
                            defects.append((fn.split('/')[-1], cur[0], d, txt[:pos].count('\n')+1))
            i=j
        else: i+=1
print('proof envs attached to a preceding statement:', attached, '| orphans:', orphan_proofs)
print('DEFECTS (proof-level leanok on probe-measured sorryAx carrier):', len(defects))
for d in defects: print('   ', d)
